def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_opp = history[-1][1]
    if n < 4:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    opp_rate = opp_c / n

    # Strongly cooperative opponents: cooperate, but exploit near the end.
    if opp_rate >= 0.9:
        if n >= 94:
            return 'D'
        return 'C'

    # Strongly defective opponents: mostly defect, with rare probes.
    if opp_rate <= 0.15 and n >= 12:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # End-game exploitation of generally cooperative partners.
    if n >= 95:
        if opp_rate >= 0.6:
            return 'D'
        return 'D' if last_opp == 'C' else 'C'

    # Track recent behavior over a modest window.
    window = 10
    recent = history[-window:] if n >= window else history
    opp_recent_c = sum(1 for a, b in recent if b == 'C')
    w = len(recent)
    opp_recent_rate = opp_recent_c / w

    # Detect sustained opponent cooperation: lock in mutual cooperation.
    if opp_recent_rate >= 0.9:
        return 'C'

    # Alternating/retaliation-heavy patterns: try to break cycles with C.
    if n >= 4:
        last4 = [history[i][1] for i in range(n - 4, n)]
        if last4 == ['D', 'C', 'D', 'C'] or last4 == ['C', 'D', 'C', 'D']:
            return 'C'

    # Opponent mostly defective recently: defect, but occasionally offer repair.
    if opp_recent_rate <= 0.2:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # If opponent just defected after a cooperative streak, punish briefly.
    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'C':
            # Single retaliation, then likely return to cooperation.
            if my_c / n > 0.6:
                return 'D'
            return 'D' if rng.random() < 0.7 else 'C'
        # Continued defection: keep punishing but occasionally forgive.
        if opp_recent_rate < 0.4:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last.
    # Avoid being exploited heavily: if we cooperate far more than they do, defect occasionally.
    if my_c > opp_c + 6 and n >= 20:
        if rng.random() < 0.35:
            return 'D'
    # Otherwise cooperate to preserve mutual cooperation.
    return 'C'
